"""Loan configuration and payment calculation for the amortization tool."""

from dataclasses import dataclass


@dataclass
class Loan:
    principal: float
    annual_rate: float
    term_months: int
    annual_tax: float = 0.0
    annual_insurance: float = 0.0
    extra_payment: float = 0.0

    @property
    def monthly_payment(self) -> float:
        r = self.annual_rate / 12
        n = self.term_months
        if r == 0:
            return self.principal / n
        factor = (1 + r) ** n
        return self.principal * r * factor / (factor - 1)

"""Interest accrual and escrow account updates for a single period."""

from loan import Loan


def compute_interest(balance: float, annual_rate: float) -> float:
    return balance * (annual_rate / 12)


def roll_balance(balance: float, principal_due: float, extra_paid: float) -> float:
    return balance - principal_due - extra_paid


def apply_escrow(escrow_balance: float, loan: Loan, period: int):
    deposit = (loan.annual_tax + loan.annual_insurance) / 12
    escrow_balance += deposit

    disbursed = 0.0
    if period % 6 == 0:
        disbursed = (loan.annual_tax + loan.annual_insurance) / 2
        escrow_balance = _settle_disbursement(escrow_balance, disbursed)

    return escrow_balance, disbursed


def _settle_disbursement(escrow_balance: float, disbursed: float) -> float:
    return escrow_balance + disbursed
